using System;using System.IO;using System.Text;using System.Globalization;using System.Windows.Forms;
namespace ScoreModern { public sealed partial class Editor {
 bool pendingParameterExport;
 bool SubmitParameterExport(string text){if(!pendingParameterExport)return false;string name=text.Trim();if(name.Length==0)name="params";string path=NativeOutputLocation.RequireWritableDestination(source,Path.GetFullPath(name));var output=new StringBuilder();foreach(var item in score.Items)output.Append(FormatParameterExportRow(item)).Append("\r\n");ScoreFileStorage.Write(path,Encoding.GetEncoding(437).GetBytes(output.ToString()));pendingParameterExport=false;Message("");return true;}
 // Original PMX fixtures verify the sign cutoff separately for2/3/4-decimal fields.
 // Keep this field rule separate from unrelated formatter callers until measured there.
 static string ExportFixed(float number,int places){string value=ScoreModern.RecoveredFragments.SingleFixedDecimal.Format(number==0||(places==2||places==3||places==4)&&Math.Abs((double)number)<Math.Pow(10,-places-1)?0f:number,places);if(value.StartsWith("0.",StringComparison.Ordinal))return value.Substring(1);if(value.StartsWith("-0.",StringComparison.Ordinal))return "-"+value.Substring(2);return value;}
 static string FormatParameterExportRow(Item item){var row=new StringBuilder();if(item.Code==11||item.Code==15){row.Append(ExportFixed(item.P(1),0).PadLeft(2)).Append((ExportFixed(item.P(2),0)+".").PadLeft(4));for(int p=3;p<=12;p++)row.Append(ExportFixed(item.P(p),3).PadLeft(10));row.Append("\r\n").Append(Encoding.GetEncoding(437).GetString(item.Bytes,56,Math.Min(item.Code==11?5:24,Math.Max(0,item.Bytes.Length-56))));return row.ToString();}if(item.Code==16){row.Append('t').Append((ExportFixed(item.P(2),0)+".").PadLeft(4));for(int p=3;p<=11;p++)row.Append(ExportFixed(item.P(p),3).PadLeft(9));row.Append("\r\n").Append(item.Text);return row.ToString();}if(item.Count>30)throw new NotSupportedException("PMX records above30 parameters are awaiting original file verification.");int[] places={0,1,3,2,2,2,4};int[] widths={0,5,8,9,9,9,11};for(int p=1;p<=item.Count;p++){int field=(p-1)%20+1;if(field==1&&p>1)row.Append("\r\n");string value=ExportFixed(item.P(p),field<=7?places[field-1]:2);if(field==1)value+=".";row.Append(value.PadLeft(field<=7?widths[field-1]:field<=12?9:10));}return row.ToString();}
 bool ParameterExportKey(KeyEventArgs key){if(!pendingParameterExport)return false;if(key.KeyCode==Keys.Escape){pendingParameterExport=false;command.Clear();Message("");key.SuppressKeyPress=true;return true;}if(key.Control||key.Alt||key.KeyCode>=Keys.F1&&key.KeyCode<=Keys.F24){key.SuppressKeyPress=true;return true;}return false;}
 }}
